def apply_specific_rules(s: str) -> str:
    """Apply the ordered transformation rules described in the task to *s*.
    Rules (in order):
    1. If length > 15, remove the middle character.
    2. If the string contains an even number of 'b's (at least one), append 'ab'.
    3. If the string ends with 'ac', replace it with 'cb'.
    4. If the string starts with 'ab', replace it with 'ca'.
    The process repeats until no rule changes the string or a state repeats.
    """
    def rule1(st: str) -> str | None:
        if len(st) > 15:
            mid = len(st) // 2
            return st[:mid] + st[mid + 1:]
        return None

    def rule2(st: str) -> str | None:
        b_count = st.count('b')
        return st + 'ab' if b_count >= 1 and b_count % 2 == 0 else None

    def rule3(st: str) -> str | None:
        return st[:-2] + 'cb' if st.endswith('ac') else None

    def rule4(st: str) -> str | None:
        return 'ca' + st[2:] if st.startswith('ab') else None

    return apply_ordered_string_rules(s, [rule1, rule2, rule3, rule4])

def apply_custom_ordered_rules_task(s: str) -> str:
